import os
import sys
import json
import logging
import subprocess
from pathlib import Path
from typing import Any, Dict, Optional

# Configure logging to avoid exposing stack traces in logs
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[logging.StreamHandler(sys.stdout)]
)
logger = logging.getLogger(__name__)

class DEXConfigLoader:
    def __init__(self, config_path: Optional[str] = None):
        self.config_path = config_path
        self.config_data: Dict[str, Any] = {}
        self._validate_config_path()

    def _validate_config_path(self) -> None:
        if self.config_path:
            try:
                resolved_path = Path(self.config_path).resolve()
                # Ensure the path is within the expected base directory or is absolute and safe
                if not resolved_path.is_file():
                    raise ValueError(f"Config file not found: {self.config_path}")
                # Sanitize to prevent path traversal
                if '..' in self.config_path:
                    raise ValueError("Invalid path traversal attempt detected")
                self.config_path = str(resolved_path)
            except Exception as e:
                logger.error(f"Failed to validate config path: {e}")
                raise ValueError("Invalid configuration path provided")

    def load_config(self) -> Dict[str, Any]:
        if not self.config_path:
            logger.warning("No config path provided, using defaults or environment variables")
            return {}

        try:
            with open(self.config_path, 'r', encoding='utf-8') as f:
                content = f.read()
                self.config_data = json.loads(content)
                return self.config_data
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON in config file: {e}")
            raise ValueError("Configuration file contains invalid JSON")
        except FileNotFoundError:
            logger.error(f"Configuration file not found: {self.config_path}")
            raise FileNotFoundError(f"Config file not found: {self.config_path}")
        except PermissionError:
            logger.error(f"Permission denied reading config file: {self.config_path}")
            raise PermissionError(f"Permission denied reading config file: {self.config_path}")
        except Exception as e:
            logger.error(f"Unexpected error loading config: {e}")
            raise RuntimeError("An unexpected error occurred while loading configuration")

    def get_api_key(self) -> Optional[str]:
        # Retrieve API key from environment variable if not in config
        env_key = os.getenv("DEX_API_KEY")
        if env_key:
            return env_key
        return self.config_data.get("api_key")

    def get_secret_key(self) -> Optional[str]:
        # Retrieve secret key from environment variable if not in config
        env_key = os.getenv("DEX_SECRET_KEY")
        if env_key:
            return env_key
        return self.config_data.get("secret_key")

class TradingExecutor:
    def __init__(self, config_loader: DEXConfigLoader):
        self.config_loader = config_loader
        self.api_key = self.config_loader.get_api_key()
        self.secret_key = self.config_loader.get_secret_key()

    def execute_trade(self, action: str, symbol: str, amount: float) -> Dict[str, Any]:
        if not action or not symbol:
            logger.error("Missing required trade parameters: action or symbol")
            raise ValueError("Missing required trade parameters")

        if not isinstance(amount, (int, float)) or amount <= 0:
            logger.error("Invalid amount provided")
            raise ValueError("Invalid amount provided")

        # Sanitize inputs to prevent injection in subprocess calls
        sanitized_action = self._sanitize_input(action)
        sanitized_symbol = self._sanitize_input(symbol)

        try:
            # Simulate secure subprocess call with strict input validation
            # In a real scenario, this would be a call to an API or a secure binary
            # We use subprocess.run with shell=False and explicit arguments to prevent injection
            cmd = [
                "echo", 
                f"Executing {sanitized_action} for {sanitized_symbol} amount {amount}"
            ]

            # Log the action without exposing secrets
            logger.info(f"Executing trade: {sanitized_action} {sanitized_symbol} {amount}")

            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=10,
                check=False
            )

            if result.returncode != 0:
                logger.error(f"Trade execution failed: {result.stderr}")
                return {"status": "failed", "error": "Trade execution failed"}

            return {"status": "success", "output": result.stdout}

        except subprocess.TimeoutExpired:
            logger.error("Trade execution timed out")
            return {"status": "failed", "error": "Trade execution timed out"}
        except subprocess.SubprocessError as e:
            logger.error(f"Subprocess error during trade: {e}")
            return {"status": "failed", "error": "Subprocess error"}
        except Exception as e:
            logger.error(f"Unexpected error during trade execution: {e}")
            return {"status": "failed", "error": "Unexpected error"}

    def _sanitize_input(self, input_str: str) -> str:
        # Remove potentially dangerous characters to prevent injection
        allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
        sanitized = "".join(c for c in input_str if c in allowed_chars)
        if not sanitized:
            raise ValueError("Input contains only invalid characters")
        return sanitized

    def log_sensitive_data(self, data: Dict[str, Any]) -> None:
        # Ensure sensitive data is not logged in plain text
        safe_data = data.copy()
        if "api_key" in safe_data:
            safe_data["api_key"] = "***REDACTED***"
        if "secret_key" in safe_data:
            safe_data["secret_key"] = "***REDACTED***"
        logger.info(f"Data processed: {safe_data}")

def main():
    config_path = os.getenv("DEX_CONFIG_PATH")
    try:
        loader = DEXConfigLoader(config_path)
        config = loader.load_config()
        executor = TradingExecutor(loader)

        # Example trade execution
        result = executor.execute_trade("BUY", "ETH-USD", 1.5)
        print(json.dumps(result))

        # Demonstrate secure logging
        executor.log_sensitive_data({"api_key": "secret123", "action": "BUY"})

    except ValueError as e:
        logger.error(f"Validation error: {e}")
        sys.exit(1)
    except FileNotFoundError as e:
        logger.error(f"File not found: {e}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"Critical error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
